INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.01', '一般过去时（强化） · Past Simple (Advanced)', 'A2', 8, '对应：8A 全册基础', E'📚 一、理论讲解\n【结构】 主语 + 动词过去式 + 其他 / Did + 主语 + 动词原形 + 其他?\n【用法】\n1. 表过去某时发生的动作或状态。\n2. 表过去经常或反复发生的动作。\n3. 常与时间状语连用：yesterday, last week, ago, in 2020 等。\n【例句】\n• I visited Beijing last summer.（我去年夏天去了北京。）\n• She didn''t go to school yesterday.（她昨天没去学校。）\n• Did you finish your homework?（你做完作业了吗？）\n【⚠️ 易错点】\n✗ I goed to school. → ✓ I went to school.（go 是不规则动词）\n✗ Did you saw him? → ✓ Did you see him?（Did 后接动词原形）\n常见不规则动词：go-went, see-saw, have-had, take-took, come-came, do-did, make-made, get-got', '[]'::jsonb, 10 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.02', '现在进行时 vs 一般现在时 · Present Continuous vs Simple Present', 'A2', 8, '对应：初一回顾对比', E'📚 一、理论讲解\n【结构】 现在进行时：主语 + am/is/are + V-ing\n一般现在时：主语 + 动词原形（第三人称单数加 s）\n【用法】\n现在进行时：表此刻正在发生的动作（now, look!, listen!）。\n一般现在时：表习惯性、客观真理（every day, usually, often）。\n【例句】\n• Look! The boys are playing football.\n• I usually go to school by bike.\n• Water boils at 100°C.\n【⚠️ 易错点】\n✗ I am liking music. → ✓ I like music.（状态动词不用进行时）\n状态动词：like, love, know, want, need, have（拥有）\nLook! / Listen! / Now / At the moment 是进行时标志', '[]'::jsonb, 20 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.03', '一般将来时综合（will / be going to） · Future Tenses', 'A2', 8, '对应：8A U7', E'📚 一、理论讲解\n【结构】 主语 + will + 动词原形 / 主语 + am/is/are going to + 动词原形\n【用法】\nwill：当场决定、主观判断、客观必然。\nbe going to：已有的计划、基于现有迹象的预测。\n时间状语：tomorrow, next week, in the future, soon\n【例句】\n• I''ll help you carry the bag.（当场决定）\n• Look at those clouds! It''s going to rain.（基于迹象）\n• We are going to visit Yunnan next summer.（已有计划）\n【⚠️ 易错点】\n✗ It will to rain. → ✓ It will rain.\nif/when 引导的状语从句不用 will，用一般现在时表将来。', '[]'::jsonb, 30 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.04', '形容词比较级（强化） · Comparatives (Advanced)', 'A2', 8, '对应：8A U3', E'📚 一、理论讲解\n【结构】 形容词比较级 + than + 比较对象\n【构成】\n单音节加 er：tall-taller\n双写末尾辅音：hot-hotter, big-bigger\n去 e 加 r：large-larger\ny 变 i 加 er：easy-easier, busy-busier\n多音节用 more：difficult-more difficult\n不规则：good/well-better, bad-worse, much/many-more, little-less\n【例句】\n• Tom is taller than his brother.\n• Math is more difficult than English.\n【⚠️ 易错点】\n✗ He is more taller. → ✓ He is taller.\nmuch / even / a little / a lot 修饰比较级。', '[]'::jsonb, 40 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.05', '副词比较级与最高级 · Adverb Comparatives & Superlatives', 'A2', 8, '对应：8A U4', E'📚 一、理论讲解\n【结构】 副词比较级 + than / (the) + 副词最高级\n【构成】\nfast/hard/early 单音节副词加 er/est\n以 ly 结尾用 more/most：slowly-more slowly-most slowly\n不规则：well-better-best, badly-worse-worst\n【例句】\n• Lin runs faster than Wang.\n• Of all the students, Mike works hardest.\n【⚠️ 易错点】\n✗ She sings more beautiful. → ✓ She sings more beautifully.\n副词最高级前 the 可省略。', '[]'::jsonb, 50 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.06', '不定代词 something / anything / nothing · Indefinite Pronouns', 'A2', 8, '对应：8A U1', E'📚 一、理论讲解\nsome- 系列：肯定句\nany- 系列：疑问句、否定句\nno- 系列：否定意义\nevery- 系列：表全部\n礼貌请求/邀请的疑问句仍用 some。\n【例句】\n• I have something to tell you.\n• Is there anything in the box?\n• There is nothing in the room.\n【⚠️ 易错点】\n✗ I want hot something. → ✓ I want something hot.（形容词后置）\n✗ I didn''t buy nothing. → ✓ I didn''t buy anything.\nEverybody 视为单数主语。', '[]'::jsonb, 60 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.07', '频度副词 always / usually / often · Frequency Adverbs', 'A2', 8, '对应：8A U2', E'📚 一、理论讲解\n频率：always > usually > often > sometimes > seldom/rarely > never\n【位置】\n实义动词前；be 动词后；助动词/情态动词后。\nsometimes 也可放句首/句末。\n【例句】\n• I always go to school by bike.\n• Tom is never late for class.\n【⚠️ 易错点】\n✗ I always am late. → ✓ I am always late.\n✗ He plays often basketball. → ✓ He often plays basketball.', '[]'::jsonb, 70 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.08', 'how often 与频率回答 · How often + frequency answers', 'A2', 8, '对应：8A U2', E'📚 一、理论讲解\n【结构】 How often + do/does + 主语 + 动词原形?\n回答：every day, once a week, twice a month, three times a year, sometimes\n【例句】\n• How often do you exercise? — Three times a week.\n• How often does the bus come? — Every 10 minutes.\n【⚠️ 易错点】\n✗ three time a week → ✓ three times a week\nevery day（两词）= 每天；everyday（一词）= 形容词''日常的''', '[]'::jsonb, 80 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.09', '形容词最高级 (the most ...) · Adjective Superlatives', 'A2', 8, '对应：8A U3', E'📚 一、理论讲解\n【结构】 the + 形容词最高级 + 范围（in/of...）\n三者或以上比较用最高级。\n范围 in（地点/团体）/ of（数量/同类）。\none of the + 最高级 + 复数名词。\n【例句】\n• The Yangtze is the longest river in China.\n• Beijing is one of the biggest cities in China.\n【⚠️ 易错点】\n✗ Lin is more tallest. → ✓ Lin is the tallest.\n✗ one of biggest cities → ✓ one of the biggest cities', '[]'::jsonb, 90 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.10', '感官动词 + 形容词 (look / smell / taste) · Sense Verbs + Adjectives', 'A2', 8, '对应：8A U2', E'📚 一、理论讲解\n【结构】 look/sound/smell/taste/feel + 形容词\n感官系动词后接形容词作表语，不用副词。\nlook like / sound like + 名词。\n【例句】\n• The flower smells sweet.\n• Your idea sounds great.\n【⚠️ 易错点】\n✗ She looks sadly. → ✓ She looks sad.\nlovely 是形容词，可作表语。', '[]'::jsonb, 100 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.11', '动词不定式 (to + 动词原形) · Infinitive', 'A2', 8, '对应：8A U6', E'📚 一、理论讲解\n【结构】 to + 动词原形\n用法：作宾语 / 作目的状语 / 作定语 / 作表语\nIt is + adj + to do something.\n【例句】\n• I want to be a teacher.\n• Tom went to the library to borrow books.\n• Do you have anything to drink?\n【⚠️ 易错点】\n✗ I want be a doctor. → ✓ I want to be a doctor.\n情态动词后不用 to：can do, must do, should do', '[]'::jsonb, 110 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.12', '动名词 (V-ing 作主语 / 宾语) · Gerund', 'A2', 8, '对应：8A U5', E'📚 一、理论讲解\n动名词 = 动词 + ing\n用法：作主语（视为单数）/ 作宾语（enjoy/finish/mind/keep/practice + V-ing）/ 介词后\nbe good at / thank for / look forward to + V-ing\n【例句】\n• Reading English every day is important.\n• I enjoy listening to music.\n• Thank you for helping me.\n【⚠️ 易错点】\n✗ I enjoy to listen. → ✓ I enjoy listening.\nstop to do（停下来去做）vs stop doing（停止做）', '[]'::jsonb, 120 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.13', 'want / hope / decide / plan + to do · Verbs followed by to-infinitive', 'A2', 8, '对应：8A U6', E'📚 一、理论讲解\nwant / hope / decide / plan / promise / agree / refuse + to do\nask / tell / teach / order sb to do something.\nI would like to do（更礼貌）。\n【例句】\n• I want to be a doctor.\n• Mom asked me to clean my room.\n【⚠️ 易错点】\n✗ Tom hopes visiting Beijing. → ✓ Tom hopes to visit Beijing.', '[]'::jsonb, 130 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.14', '反身代词 (myself / yourself / ...) · Reflexive Pronouns', 'A2', 8, '对应：8B U1', E'📚 一、理论讲解\nmyself/yourself/himself/herself/itself/ourselves/yourselves/themselves\n用法：作宾语 / 加强语气 / 介词宾语（by oneself, help oneself to）\nenjoy oneself = have a good time\n【例句】\n• I made the cake myself.\n• Take care of yourself.\n• She did the homework by herself.\n【⚠️ 易错点】\n✗ Take care of you. → ✓ Take care of yourself.\n✗ theirselves → ✓ themselves', '[]'::jsonb, 140 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.15', 'how + adj 提问 (how long / how far) · How + Adjective Questions', 'A2', 8, '对应：8A U2', E'📚 一、理论讲解\nHow long（时长/长度）/ How far（距离）/ How tall（人身高）/ How high（建筑/山）\nHow wide / deep / old / heavy\nHow much（不可数/价钱）/ How many（可数）/ How often（频率）\n【例句】\n• How tall is Yao Ming? — 2.26 meters.\n• How far is your school? — 2 km.\n• How long have you studied English? — 5 years.\n【⚠️ 易错点】\n✗ How long is your father?（身高）→ ✓ How tall is your father?\n✗ How many is the bag?（价钱）→ ✓ How much is the bag?', '[]'::jsonb, 150 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.16', '邀请与建议 (Would you like / Why don''t you) · Invitations & Suggestions', 'A2', 8, '对应：8A U5', E'📚 一、理论讲解\nWould you like to do?（礼貌邀请）\nWhy don''t you/we + 动词原形? / Why not + 动词原形?\nHow/What about + V-ing/名词?\nLet''s + 动词原形 / Shall we + 动词原形?\n【例句】\n• Would you like to come to my party?\n• How about going swimming?\n• Let''s go to the cinema, shall we?\n【⚠️ 易错点】\n✗ How about to go? → ✓ How about going?（about 是介词）\n✗ Why not playing chess? → ✓ Why not play chess?', '[]'::jsonb, 160 FROM junior_grammar_categories WHERE code = 'other';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.17', 'if 引导的条件状语从句 · If-Conditional (Real)', 'B1', 8, '对应：8B U4', E'📚 一、理论讲解\n【结构】 If + 一般现在时, 主语 + will + 动词原形\nif 从句表条件，主句表结果。条件状语从句不用 will，用一般现在时表将来。\nunless = if not（除非）\n【例句】\n• If it rains tomorrow, we will stay at home.\n• I won''t go unless you come with me.\n【⚠️ 易错点】\n✗ If it will rain, we will stay home. → ✓ If it rains, we will stay home.\nif 从句单数主语用第三人称单数：If she comes early...', '[]'::jsonb, 170 FROM junior_grammar_categories WHERE code = 'clause';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.18', 'should / shouldn''t 表建议 · Modal: should', 'A2', 8, '对应：8B U2', E'📚 一、理论讲解\n【结构】 主语 + should/shouldn''t + 动词原形\nshould = 应该（建议、义务）\nWhat should I do? = 我该怎么办？\n情态动词无人称变化，后接动词原形。\n【例句】\n• You should eat more vegetables.\n• Children shouldn''t stay up late.\n【⚠️ 易错点】\n✗ You should to eat fruit. → ✓ You should eat fruit.\n✗ She shoulds → ✓ She should（无人称变化）', '[]'::jsonb, 180 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.19', 'have to / must 表义务 · Modal: have to / must', 'A2', 8, '对应：8B U1', E'📚 一、理论讲解\nhave to = 必须（外部规定/客观需要，有人称/时态变化：has to / had to）\nmust = 必须（说话人主观要求，没有过去式）\ndon''t have to = 不必（无必要）\nmustn''t = 禁止（强烈不可）\n【例句】\n• I have to get up at 6.\n• Children mustn''t play with fire.\n• Yesterday I had to work late.\n【⚠️ 易错点】\n区别：mustn''t（禁止）vs don''t have to（不必）\n✗ She have to → ✓ She has to', '[]'::jsonb, 190 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.20', 'could / would 礼貌请求 · Polite Requests', 'A2', 8, '对应：8B U3', E'📚 一、理论讲解\nCould you ...?（请求别人）/ Could I ...?（请求许可）\nWould you please + 动词原形?\nWould you mind + V-ing?（介意……吗，接动名词）\nWould you like ...?（提供）\n【例句】\n• Could you help me, please?\n• Would you mind opening the window?\n【⚠️ 易错点】\n✗ Would you mind to open? → ✓ Would you mind opening?\nCould you 的肯定回答用 Yes, sure / Of course。', '[]'::jsonb, 200 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.21', 'when / while 时间状语从句 · Time Clauses: when / while', 'B1', 8, '对应：8B U6', E'📚 一、理论讲解\nwhen：用于短动作（一般过去时），表''当……时''。\nwhile：用于持续动作（过去进行时），表''在……的时候''。\n【例句】\n• I was reading when my mom called me.\n• While I was doing homework, Tom was watching TV.\n• When I was 5, I started piano.\n【⚠️ 易错点】\n记忆口诀：when（短）/ while（长）。\n✗ While I did homework, Tom was playing. → ✓ While I was doing homework, Tom was playing.', '[]'::jsonb, 210 FROM junior_grammar_categories WHERE code = 'clause';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.22', '过去进行时 (was/were + V-ing) · Past Continuous', 'B1', 8, '对应：8B U6', E'📚 一、理论讲解\n【结构】 主语 + was/were + V-ing + 其他\n用法：表过去某时刻正在进行的动作；过去一段时间持续的动作；与 while 连用表两动作同时。\n时间标志：at this time yesterday, when..., while..., from...to...\n【例句】\n• I was watching TV at 8 last night.\n• What were you doing when I called?\n【⚠️ 易错点】\n✗ Tom were reading. → ✓ Tom was reading.（单数用 was）\n✗ At 9 last night I read. → ✓ At 9 last night I was reading.', '[]'::jsonb, 220 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.23', '过去进行时 + 一般过去时（同时 vs 突发） · Past Continuous vs Past Simple', 'B1', 8, '对应：8B U6', E'📚 一、理论讲解\n【结构】 主句过去进行时 + when + 从句一般过去时\n持续动作（背景）→ 过去进行时；突发动作 → 一般过去时。\n【例句】\n• I was watching TV when the phone rang.\n• While I was reading, the lights went out.\n【⚠️ 易错点】\n✗ I was watching TV when the phone was ringing. → ✓ ...when the phone rang.\n判断：背景（持续）→ 过去进行时；事件（短突发）→ 一般过去时。', '[]'::jsonb, 230 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.24', '现在完成时 (have/has + 过去分词) · Present Perfect', 'B1', 8, '对应：8B U9', E'📚 一、理论讲解\n【结构】 主语 + have/has + 过去分词 + 其他\n用法：过去发生但与现在有联系；从过去某时持续到现在（for + 时长 / since + 时间点）。\n时间标志：already, just, yet, ever, never, recently, this week, twice, three times\nhave been to（去过）vs have gone to（去了）。\n【例句】\n• I have already finished my homework.\n• Lin has been to Beijing twice.\n• Tom has lived here for 3 years.\n【⚠️ 易错点】\n✗ I have seen the movie last week. → ✓ I saw the movie last week.（不能与具体过去时间连用）', '[]'::jsonb, 240 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.25', '现在完成时 vs 一般过去时 · Present Perfect vs Past Simple', 'B1', 8, '对应：8B U9', E'📚 一、理论讲解\n现在完成时：与现在有联系，不能与具体过去时间连用。\n一般过去时：纯粹过去发生，可与具体过去时间连用（yesterday, last week, in 2020, ago）。\n关键词：完成时（already/just/yet/ever/never/since/for/this year）；过去时（yesterday/last/ago/in + 年份）。\n【例句】\n• I have lived here for 5 years.\n• I lived here when I was 8.\n【⚠️ 易错点】\n✗ I have visited Beijing last summer. → ✓ I visited Beijing last summer.\n✗ When have you finished? → ✓ When did you finish?', '[]'::jsonb, 250 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.26', '宾语从句 (that / if / wh-) · Object Clauses', 'B1', 8, '对应：9 衔接', E'📚 一、理论讲解\n陈述句作宾从用 that（可省）；一般疑问句用 if/whether；特殊疑问句用原疑问词。\n三个原则：连接词 + 陈述语序 + 时态一致。\n【例句】\n• I think (that) he is a good student.\n• She asked if I liked Chinese food.\n• Tell me where you live.\n【⚠️ 易错点】\n✗ Tell me where do you live. → ✓ Tell me where you live.（陈述语序）\n时态一致：主句过去时，从句相应后退。', '[]'::jsonb, 260 FROM junior_grammar_categories WHERE code = 'clause';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.27', '被动语态 (be + 过去分词) · Passive Voice', 'B1', 8, '对应：9 衔接', E'📚 一、理论讲解\n【结构】 主语 + be + 过去分词 + (by + 动作执行者)\n各时态被动：am/is/are done / was/were done / am/is/are being done / have/has been done / will be done\n【例句】\n• English is spoken in many countries.\n• The Great Wall was built thousands of years ago.\n• A new school will be built next year.\n【⚠️ 易错点】\n✗ A new school is built next year. → ✓ A new school will be built next year.\n必须用过去分词，不是过去式。', '[]'::jsonb, 270 FROM junior_grammar_categories WHERE code = 'verb';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.28', '定语从句 (who / which / that) · Relative Clauses', 'B1', 8, '对应：9 衔接', E'📚 一、理论讲解\nwho（指人作主语）/ whom（指人宾语）/ which（指物）/ that（人或物，更常用）/ whose（所有格）。\n【例句】\n• The boy who is wearing glasses is my brother.\n• This is the book which I borrowed.\n• I have a friend whose name is Tom.\n【⚠️ 易错点】\n✗ The boy which is wearing glasses → ✓ The boy who...\n✗ The friend who name is Tom → ✓ The friend whose name is Tom', '[]'::jsonb, 280 FROM junior_grammar_categories WHERE code = 'clause';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.29', '现在完成进行时 (have been doing) · Present Perfect Continuous', 'B2', 8, '对应：9 进阶', E'📚 一、理论讲解\n【结构】 主语 + have/has + been + V-ing\n强调从过去某时持续到现在的动作（仍在进行）。\n现在完成时：强调结果；现在完成进行时：强调过程/持续。\n时间标志：for + 时长、since + 时间点、recently、all morning。\n【例句】\n• I have been learning English for 5 years.\n• It has been raining for hours.\n【⚠️ 易错点】\n状态动词不用进行时：know, like, love, want（用现在完成时即可）。', '[]'::jsonb, 290 FROM junior_grammar_categories WHERE code = 'tense';
INSERT INTO junior_grammar_points (category_id, code, title, cefr, grade, summary, explanation_md, examples, sort_order) SELECT id, 'g8.30', '虚拟语气入门 (If I were ...) · Subjunctive (Introductory)', 'B2', 8, '对应：9 进阶', E'📚 一、理论讲解\n【结构】 If + 主语 + 过去式 (be 用 were), 主语 + would/could + 动词原形\n表与现在事实相反的假设。\nI wish + 虚拟语气：I wish I were taller.\n【例句】\n• If I were you, I would study harder.\n• If I had time, I would help you.\n• I wish I were a bird.\n【⚠️ 易错点】\n✗ If I am you → ✓ If I were you\n✗ I wish I was taller → ✓ I wish I were taller', '[]'::jsonb, 300 FROM junior_grammar_categories WHERE code = 'clause';